      when(mockCurrencyRepository.fetchRates(argThat(isA<CurrencyPageRequest>().having((r) => r.page, 'page', 0))))
          .thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: true));
      when(mockCurrencyRepository.fetchRates(argThat(isA<CurrencyPageRequest>().having((r) => r.page, 'page', 1))))
          .thenAnswer((_) async => CurrencyPage(items: [currencyItems.first], page: 1, hasMore: false));

      await tester.pumpWidget(buildPage());
      await tester.pumpAndSettle();

      expect(find.byType(ShowMoreButton), findsOneWidget);
      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));

      await tester.tap(find.byType(ShowMoreButton));
